// Critical regressions reviewed/updated by Cypress Author — 2026-11-17.
// Real page/assets, captured quote replay. NOT real backend integration/pricing.
import observed from '../../../fixtures/ordering-observed.json';
import captured from '../../../fixtures/ordering-quotes.json';
import audit from '../../../fixtures/ordering-audit-quotes.json';
import {
  ui, productIdentity, replayPresentation, observeQuoteLifecycle, afterBrowserRender,
  selectedPackage, waitForQuoteTerminal, latestQuotePresentation, quoteWasCancelled
} from '../../../support/ordering';

describe('M04 P08/P10/P11 — controlled quote presentation and latest-selection regression', () => {
  // Cypress discards pending intercepts at test isolation. Do not reply from an
  // afterEach hook after the request has already been cancelled on failure.
  it('P08-ORD01 — presents the exact captured quote without claiming financial correctness', () => {
    const entry = captured.responses.initial;
    cy.intercept('POST', observed.quotePath, req => {
      expect(req.body, 'replay input must match the actual captured input').deep.eq(entry.input);
      req.reply({ statusCode: entry.status, body: entry.body });
    }).as('replay');
    cy.visit(observed.product.path);
    productIdentity();
    cy.wait('@replay').its('response.statusCode').should('eq', 200);
    replayPresentation(entry.body);
    // The original normalized helper did not assert Persian glyphs/grouping.
    const faMoney = value => new Intl.NumberFormat('fa-IR').format(value) + ' ریال';
    cy.get(ui.total).should($el => expect($el.text().trim()).eq(faMoney(entry.body.line_total_irr)));
    cy.get(ui.unit).should('contain.text', faMoney(entry.body.unit_price_irr));
    cy.get(ui.perLabel).should('contain.text', faMoney(entry.body.price_per_label_irr));
  });

  it('P10-ORD01 — an older quote completion cannot overwrite the latest selection', () => {
    let releaseOlder;
    let released = false;
    const lifecycle = [];
    const observerEnabled = Cypress.expose('quoteLifecycleObserver') !== false;
    cy.intercept('POST', observed.quotePath, req => {
      const quantity = req.body.quantity;
      const entry = quantity === 1 ? captured.responses.initial
        : quantity === 2 ? captured.responses.quantity2
          : quantity === 3 ? captured.responses.quantity3 : null;
      expect(entry, 'only the three inspected inputs may be replayed').to.exist;
      expect(req.body, 'do not invent package or request contract').deep.eq(entry.input);
      if (quantity === 2) {
        req.alias = 'older';
        // Cypress awaits the returned Promise; no cy commands inside the handler.
        return new Cypress.Promise(resolve => {
          releaseOlder = () => {
            if (released) return;
            released = true;
            if (!quoteWasCancelled(lifecycle, entry.input)) {
              req.reply({ statusCode: entry.status, body: entry.body });
            }
            resolve();
          };
        });
      }
      req.alias = quantity === 1 ? 'initial' : 'latest';
      req.reply({ statusCode: entry.status, body: entry.body });
    });
    cy.visit(observed.product.path, {
      onBeforeLoad(win) { if (observerEnabled) observeQuoteLifecycle(win, lifecycle); }
    });
    cy.wait('@initial');
    productIdentity();
    replayPresentation(captured.responses.initial.body);
    cy.get(ui.increase).click();
    cy.wrap(null).should(() => expect(releaseOlder, 'older request has entered the gate').to.be.a('function'));
    cy.get(ui.quantity).should('have.value', '2');
    // The inspected stepper + button is disabled during a pending quote. The
    // native numeric input remains enabled: use its supported keyboard path.
    cy.get(ui.quantity).focus().should('be.focused');
    cy.press(Cypress.Keyboard.Keys.UP);
    cy.press(Cypress.Keyboard.Keys.TAB);
    cy.wait('@latest').its('response.statusCode').should('eq', 200);
    latestQuotePresentation(observed.packages.default, captured.responses.quantity3);
    cy.then(() => { releaseOlder(); });
    cy.then(() => {
      expect(released, 'older response was released only after latest UI settled').eq(true);
    });
    if (observerEnabled) waitForQuoteTerminal(lifecycle, captured.responses.quantity2);
    else cy.wait('@older').then(interception => {
      expect(interception.request.body, 'exact older request').deep.eq(captured.responses.quantity2.input);
      if (interception.response) {
        expect(interception.response.statusCode, 'delivered replay').eq(200);
        expect(interception.response.body, 'exact older response').deep.eq(captured.responses.quantity2.body);
      } else {
        throw new Error('Unwrapped diagnostic requires delivery; rerun primary mode to verify native cancellation');
      }
    });
    // A clone completes independently of whether the AUT reads/discards the
    // original. Native cancellation is accepted only with its actual signal.
    if (!observerEnabled) afterBrowserRender(); // Not the primary cancellation oracle.
    latestQuotePresentation(observed.packages.default, captured.responses.quantity3);
    // No pending-CTA policy, backend race, cart, order or duplicate-charge claim.
  });

  it('P10-ORD02 — a stale package quote cannot overwrite the newer package at the same quantity', () => {
    const older = captured.responses.quantity2;
    const latest = audit.responses.alternateQuantity2;
    const lifecycle = [];
    const observerEnabled = Cypress.expose('quoteLifecycleObserver') !== false;
    let releaseOlder;
    let released = false;
    cy.intercept('POST', observed.quotePath, req => {
      const entry = req.body.quantity === 1 ? captured.responses.initial
        : req.body.package_id === older.input.package_id ? older : latest;
      expect(req.body, 'exact inspected input; no invented package or contract').deep.eq(entry.input);
      if (entry === older) {
        req.alias = 'olderPackage';
        return new Cypress.Promise(resolve => {
          releaseOlder = () => {
            if (released) return;
            released = true;
            if (!quoteWasCancelled(lifecycle, entry.input)) {
              req.reply({ statusCode: entry.status, body: entry.body });
            }
            resolve();
          };
        });
      }
      req.alias = entry === latest ? 'latestPackage' : 'initialMixed';
      req.reply({ statusCode: entry.status, body: entry.body });
    });
    cy.visit(observed.product.path, {
      onBeforeLoad(win) { if (observerEnabled) observeQuoteLifecycle(win, lifecycle); }
    });
    cy.wait('@initialMixed');
    productIdentity();
    replayPresentation(captured.responses.initial.body);
    cy.get(ui.increase).click();
    cy.wrap(null).should(() => expect(releaseOlder, 'old package request entered the gate').to.be.a('function'));
    cy.get(ui.quantity).should('have.value', '2');
    cy.contains('main button', observed.packages.alternate.title).click();
    cy.wait('@latestPackage').its('response.statusCode').should('eq', 200);
    latestQuotePresentation(observed.packages.alternate, latest);
    cy.then(() => { releaseOlder(); });
    cy.then(() => {
      expect(released, 'old response released after latest package rendered').eq(true);
    });
    if (observerEnabled) waitForQuoteTerminal(lifecycle, older);
    else cy.wait('@olderPackage').then(interception => {
      expect(interception.request.body, 'exact older package request').deep.eq(older.input);
      if (interception.response) {
        expect(interception.response.statusCode).eq(200);
        expect(interception.response.body, 'exact older package response').deep.eq(older.body);
      } else {
        throw new Error('Unwrapped diagnostic requires delivery; rerun primary mode to verify native cancellation');
      }
    });
    if (!observerEnabled) afterBrowserRender();
    latestQuotePresentation(observed.packages.alternate, latest);
  });

  it('P11-ORD01 — simulated quote unavailability announces failure and a new selection recovers', () => {
    cy.intercept('POST', observed.quotePath, req => {
      const entry = req.body.quantity === 1 ? captured.responses.initial
        : req.body.quantity === 2 ? captured.responses.quantity2 : captured.responses.quantity3;
      expect(req.body, 'only verified quantity inputs may be handled').deep.eq(entry.input);
      if (req.body.quantity === 2) {
        req.alias = 'unavailableQuote';
        req.reply({ forceNetworkError: true });
      } else {
        req.alias = req.body.quantity === 1 ? 'initialRecovery' : 'recoveredQuote';
        req.reply({ statusCode: entry.status, body: entry.body });
      }
    });
    cy.visit(observed.product.path);
    cy.wait('@initialRecovery');
    productIdentity();
    replayPresentation(captured.responses.initial.body);
    cy.get(ui.increase).click();
    cy.wait('@unavailableQuote').should('have.property', 'error');
    cy.contains('[role="alert"]', 'ارتباط برقرار نشد. دوباره تلاش کنید.').should('be.visible');
    productIdentity();
    cy.get(ui.quantity).should('have.value', '2');
    selectedPackage(observed.packages.default);
    cy.get(ui.increase).click();
    cy.wait('@recoveredQuote').its('response.statusCode').should('eq', 200);
    replayPresentation(captured.responses.quantity3.body);
    selectedPackage(observed.packages.default);
    productIdentity();
    // Does not prescribe old-price visibility, toast expiry, CTA state or same-input retry.
  });
});
